// The game. Generated by `studio game init --engine web` — this file is yours to edit.
// three.js renders, Rapier simulates. Studio assets arrive in assets/studio/ via `studio game import`;
// never edit those copies (fix them in the studio and import again).
// Keep the StudioGame fields filled in: the studio's play-test harness (studio/harness.ts) uses them
// to run, screenshot and walk the game headlessly.
import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import RAPIER from '@dimforge/rapier3d-compat';
import { addStaticColliders, installHarness, startCharacters, type StudioGame } from '../studio/harness.ts';
import { startEffects } from '../studio/effects.ts';
import { startUI } from '../studio/ui.ts';
import { applyLook } from '../studio/look.ts';

const STUDIO_SCENE = 'assets/studio/scene.glb';

async function start(): Promise<StudioGame> {
  await RAPIER.init();
  const renderer = new THREE.WebGLRenderer({ antialias: true, preserveDrawingBuffer: true });
  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
  renderer.setSize(innerWidth, innerHeight);
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFShadowMap;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  document.body.appendChild(renderer.domElement);

  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#ece9e3');
  const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.05, 200);
  camera.position.set(2.2, 1.8, 2.6);
  camera.lookAt(0, 0.4, 0);

  scene.add(new THREE.HemisphereLight('#ffffff', '#b8b2a7', 1.1));
  const sun = new THREE.DirectionalLight('#ffffff', 2.2);
  sun.position.set(3, 6, 4);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  Object.assign(sun.shadow.camera, { left: -6, right: 6, top: 6, bottom: -6 });
  scene.add(sun);

  const floor = new THREE.Mesh(new THREE.PlaneGeometry(60, 60), new THREE.MeshStandardMaterial({ color: '#9e9991', roughness: 0.95 }));
  floor.rotation.x = -Math.PI / 2;
  floor.receiveShadow = true;
  floor.position.y = -0.006; // a hair below y = 0, so studio ground (a yard, a rug) never flickers against it
  floor.name = 'Floor';
  scene.add(floor);

  const world = new RAPIER.World({ x: 0, y: -9.81, z: 0 });
  world.createCollider(RAPIER.ColliderDesc.cuboid(30, 0.1, 30).setTranslation(0, -0.1, 0));

  let studio: THREE.Object3D | null = null;
  let animations: THREE.AnimationClip[] = [];
  const res = await fetch(STUDIO_SCENE, { method: 'HEAD' }).catch(() => null);
  if (res?.ok) {
    const gltf = await new GLTFLoader().loadAsync(STUDIO_SCENE);
    studio = gltf.scene;
    animations = gltf.animations;
    studio.name = 'Studio';
    studio.traverse((o: any) => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });
    scene.add(studio);
    addStaticColliders(world, RAPIER, studio);
  }

  const game: StudioGame = {
    renderer, scene, camera, studio, world, RAPIER, animations, paused: false,
    step(dt: number) {
      world.timestep = dt;
      world.step();
      // your game logic per fixed step goes here
    },
  };

  addEventListener('resize', () => {
    renderer.setSize(innerWidth, innerHeight);
    camera.aspect = innerWidth / innerHeight;
    camera.updateProjectionMatrix();
  });
  // studio characters play their idle; the studio's player (game import --player) walks with WASD / arrows
  await startCharacters(game, { controls: true });
  // studio effects (game.effects.setValue / .event) and the UI kit's HUD (game.ui.setBar / say()) — both
  // are empty until the studio has some
  await applyLook(game);   // the studio look (look.json): sky, fog, light, grade — or keep the lights above
  await startEffects(game);
  await startUI(game);
  renderer.setAnimationLoop(() => {
    if (game.paused) return;
    game.step(1 / 60);
    game.characters?.update(1 / 60);
    renderer.render(scene, camera);
  });
  return game;
}

installHarness(start());
